import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.76ZGnlPi.js";const g=JSON.parse('{"title":"Scraper Search Integration","description":"","frontmatter":{},"headers":[],"relativePath":"admin/scraper-search/index.md","filePath":"admin/scraper-search/index.md"}'),s={name:"admin/scraper-search/index.md"};function i(o,e,n,c,p,h){return a(),r("div",null,[...e[0]||(e[0]=[d(`<h1 id="scraper-search-integration" tabindex="-1">Scraper Search Integration <a class="header-anchor" href="#scraper-search-integration" aria-label="Permalink to &quot;Scraper Search Integration&quot;">​</a></h1><p>The Scraper Search module exposes a single read-only endpoint that returns the <strong>raw, untransformed</strong> <code>OTA_AirLowFareSearchRS</code> body for a given route and date. It is intended for external scrapers that need the supplier response exactly as received — with no caching, pricing, markup, tax, or B2B transformation applied.</p><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Return the raw OTA low fare search response for scrapers</td></tr><tr><td><strong>Authentication</strong></td><td>API Key (<code>X-Api-Key</code> header), validated against <code>SCRAPER_ACCESS_API_KEY</code></td></tr><tr><td><strong>Endpoint</strong></td><td><code>GET /api/v1/scraper-search/air-low-fare-search</code></td></tr><tr><td><strong>Rate Limit</strong></td><td>100 req/min</td></tr><tr><td><strong>Caching</strong></td><td>None — every request hits the supplier live</td></tr><tr><td><strong>Transformation</strong></td><td>None — raw <code>OTA_AirLowFareSearchRS</code> body returned as-is</td></tr><tr><td><strong>Empty result</strong></td><td>Returns <code>{}</code> when the supplier reports no availability</td></tr></tbody></table><hr><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The endpoint requires a dedicated API key passed via the <code>X-Api-Key</code> header:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Api-Key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;your-scraper-access-api-key&gt;</span></span></code></pre></div><p>The key is validated against the <code>SCRAPER_ACCESS_API_KEY</code> environment variable. It is intentionally <strong>separate</strong> from the internal service key so that scraper access can be rotated or revoked independently.</p><p>The guard fails closed: if <code>SCRAPER_ACCESS_API_KEY</code> is unconfigured, or the supplied key is missing or incorrect, the request receives a <code>401 Unauthorized</code> response.</p><hr><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><h3 id="air-low-fare-search" tabindex="-1">Air Low Fare Search <a class="header-anchor" href="#air-low-fare-search" aria-label="Permalink to &quot;Air Low Fare Search&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>GET /api/v1/scraper-search/air-low-fare-search</code></p><p>Runs an OTA low fare search with the supplied query parameters and returns the raw <code>OTA_AirLowFareSearchRS</code> body.</p><p><strong>Query Parameters:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>origin</code></td><td>string</td><td>Yes</td><td>Origin station code. Exactly 3 chars, trimmed and upper-cased (e.g. <code>DMX</code>).</td></tr><tr><td><code>destination</code></td><td>string</td><td>Yes</td><td>Destination station code. Exactly 3 chars, trimmed and upper-cased (e.g. <code>MKX</code>).</td></tr><tr><td><code>departureDate</code></td><td>string</td><td>Yes</td><td>Departure date, <code>YYYY-MM-DD</code>.</td></tr><tr><td><code>returnDate</code></td><td>string</td><td>Conditional</td><td>Return date, <code>YYYY-MM-DD</code>. <strong>Required when <code>tripType=ROUND_TRIP</code></strong>, otherwise omit.</td></tr><tr><td><code>adults</code></td><td>integer</td><td>Yes</td><td>Number of adults. Range <code>1</code>–<code>9</code>.</td></tr><tr><td><code>children</code></td><td>integer</td><td>Yes</td><td>Number of children. Range <code>0</code>–<code>9</code>.</td></tr><tr><td><code>infants</code></td><td>integer</td><td>Yes</td><td>Number of infants. Range <code>0</code>–<code>9</code>.</td></tr><tr><td><code>tripType</code></td><td>enum</td><td>Yes</td><td><code>ONE_WAY</code> or <code>ROUND_TRIP</code>.</td></tr></tbody></table><p><strong>Example Request (one-way):</strong></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/scraper-search/air-low-fare-search?origin=DMX&amp;destination=MKX&amp;departureDate=2026-05-30&amp;adults=1&amp;children=0&amp;infants=0&amp;tripType=ONE_WAY</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Api-Key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;your-scraper-access-api-key&gt;</span></span></code></pre></div><p><strong>Example Request (round-trip):</strong></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/scraper-search/air-low-fare-search?origin=DMX&amp;destination=MKX&amp;departureDate=2026-05-30&amp;returnDate=2026-06-05&amp;adults=2&amp;children=1&amp;infants=0&amp;tripType=ROUND_TRIP</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Api-Key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;your-scraper-access-api-key&gt;</span></span></code></pre></div><p><strong>Responses:</strong></p><table tabindex="0"><thead><tr><th>Status</th><th>Description</th></tr></thead><tbody><tr><td><code>200</code></td><td>Raw <code>OTA_AirLowFareSearchRS</code> body, or <code>{}</code> when no availability was returned.</td></tr><tr><td><code>400</code></td><td>Invalid query parameters (e.g. bad station code length, missing <code>returnDate</code> for <code>ROUND_TRIP</code>, out-of-range passenger count).</td></tr><tr><td><code>401</code></td><td>Invalid or missing API key.</td></tr></tbody></table><p>The <code>200</code> body is the supplier response verbatim. When the supplier reports no availability (or returns a 4xx), the endpoint normalizes the result to an empty object <code>{}</code> so the response is always valid JSON.</p>`,25)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
